 public static object Reflections(){var s=Check();var root=GameObject.Find("B1_ResearchAndStaffFloor").transform;var parent=GameObject.Find("B1_Reflections")??new GameObject("B1_Reflections");parent.transform.SetParent(root,false);var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player.SetActive(false);int count=0;try{foreach(var r in JObject.Parse(File.ReadAllText(H+"layout.json"))["rooms"]){string id=(string)r["id"];var existing=parent.transform.Find("Reflection_"+id);var g=existing?existing.gameObject:new GameObject("Reflection_"+id);g.transform.SetParent(parent.transform,false);g.transform.localPosition=new Vector3((float)r["x"],2,-(float)r["v"]);var p=g.GetComponent<ReflectionProbe>()??g.AddComponent<ReflectionProbe>();float rad=(float)r["r"];p.size=new Vector3(rad*2,rad+2,rad*2);p.center=new Vector3(0,rad*.5f-2,0);p.blendDistance=1;p.resolution=128;p.hdr=true;p.boxProjection=true;p.mode=ReflectionProbeMode.Custom;p.renderDynamicObjects=true;p.clearFlags=ReflectionProbeClearFlags.SolidColor;p.backgroundColor=new Color(.08f,.08f,.07f);p.intensity=.7f;string file=E+"Textures/BL_Reflection_"+id+".exr";if(!Lightmapping.BakeReflectionProbe(p,file))throw new Exception("Probe failed: "+id);AssetDatabase.ImportAsset(file,ImportAssetOptions.ForceSynchronousImport);p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Cubemap>(file);if(!p.customBakedTexture)throw new Exception("Missing cubemap");count++;}}finally{player.SetActive(true);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();return new{probes=count};}
