 public static object Audit(){var s=Check();var root=GameObject.Find("B1_ResearchAndStaffFloor");var ts=root.GetComponentsInChildren<Transform>(true);var rs=root.GetComponentsInChildren<Renderer>(true);var fs=root.GetComponentsInChildren<MeshFilter>(true);var meshes=fs.Where(f=>f.sharedMesh).Select(f=>f.sharedMesh).Distinct().ToArray();var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));var errors=new List<string>();foreach(var p in plan["placements"]){var t=root.transform.Find("B1_"+(string)p["room"]+"_Sector/Equipment/"+(string)p["name"]);if(!t){errors.Add("Missing "+(string)p["name"]);continue;}if(Vector3.Distance(t.localPosition,V(p["position"]))>.002f)errors.Add("Position "+t.name);if(Quaternion.Angle(t.localRotation,Quaternion.Euler(0,(float)p["yaw"],0))>.01f)errors.Add("Rotation "+t.name);}
